/* Astralis tabletop extensions. State changes go through the authoritative API. */
window.AstralisWorkbench = function(ctx) {
  const {state,api,command,renderTable,selectInspectorTab,escapeHTML:e,toolField:field,notify,controlsActor,currentRoute}=ctx;
  const h=(text)=>`<h3 class="title-4">${text}</h3>`;
  const textArea=(label,name,value,max=20000)=>`<label class="field"><span class="caption-4">${label}</span><textarea class="field-input body-6" name="${name}" rows="4" maxlength="${max}">${e(value||'')}</textarea></label>`;
  const select=(label,name,options,value)=>`<label class="field"><span class="caption-4">${label}</span><select class="field-input body-6" name="${name}" aria-label="${label}">${options.map(([id,title])=>`<option value="${e(id)}" ${String(value)===String(id)?'selected':''}>${e(title)}</option>`).join('')}</select></label>`;
  const check=(label,name,value)=>`<label class="checkbox-label body-6"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
  const button=(label,attrs='',primary=false)=>`<button class="button button-${primary?'primary':'secondary'} button-sm" ${attrs}>${label}</button>`;
  const form=(id,title,body,submit)=>`<form data-vtt-form="${id}" class="tool-card stack-12">${h(title)}${body}${button(submit||'Save','',true)}</form>`;
  const draft=(id,key,fallback)=>state.vttDrafts?.[id]?.[key]??fallback;
  const world=()=>state.snapshot?.state||{};
  const canvas=window.AstralisCanvas?.(ctx);
  const actorChoices=()=> (world().actors||[]).map(a=>[a.id,a.name]);
  let gesture=null,ignoreClick=0,audio=null,audioKey='',audioEnabled=false;
  let localStream=null,connectionID='',callClients={},callError='',mediaBusy=false;
  const calls=new Map();

  function panel(gm){
    const sections=gm?['scenes','sheets','drawings','tokens','art','lighting','environment','turns','chat','journal','quests','tables','music','media','macros','settings']:['sheets','environment','chat','journal','quests','tables','music','media','macros','settings'];
    const active=sections.includes(state.vttSection)?state.vttSection:sections[0];
    return `<section id="panel-table" class="inspector-panel" role="tabpanel" aria-labelledby="tab-table" ${state.inspectorTab!=='table'?'hidden':''}><div class="tool-panel-heading"><h2 class="title-3">Table workspace</h2><span class="chip caption-4">${gm?'Game master':'Player'}</span></div>${state.playerPreview?button('Exit player preview','type="button" data-vtt-action="exit-preview"'):''}<nav class="vtt-section-nav" aria-label="Table workspace tools">${sections.map(section=>`<button type="button" class="button button-quiet button-sm ${active===section?'is-active':''}" data-vtt-section="${section}" aria-pressed="${active===section}">${section[0].toUpperCase()+section.slice(1)}</button>`).join('')}</nav><div class="vtt-section stack-16" data-vtt-content="${active}">${sectionContent(active,gm)}</div></section>`;
  }
  function sectionContent(section,gm){
    const body=sectionBody(section,gm),sheet=(world().sheets||[]).find(x=>x.id===state.sheetEdit);
    return body+(section==='sheets'&&sheet?sheetTokens(sheet,gm)+sheetEntries(sheet,gm||sheet.controller_id===state.user?.id):'');
  }
  function sheetTokens(sheet,gm){
    const linked=(world().actors||[]).filter(a=>a.sheet_id===sheet.id),f=(key,value)=>draft('sheet-place',key,value);
    // Prefer an unoccupied central cell so new tokens are clear of floating map tools.
    const w=world(),center=Math.floor(w.height/2)*w.width+Math.floor(w.width/2);let placement={x:0,y:0};
    for(let i=0;i<w.width*w.height;i++){const n=(center+i)%(w.width*w.height),x=n%w.width,y=Math.floor(n/w.width);if(!(w.blocked||[]).some(p=>p.x===x&&p.y===y)&&!(w.doors||[]).some(d=>d.x===x&&d.y===y&&!d.open)&&!(w.actors||[]).some(a=>a.hp>0&&x>=a.x&&x<a.x+(a.size||1)&&y>=a.y&&y<a.y+(a.size||1))){placement={x,y};break;}}
    return `<section class="sheet-token-controls tool-card stack-12">${h('Map tokens')}<p class="caption-4 muted">Links open this sheet from a token. HP, combat values and existing token control stay independent. New party tokens inherit the sheet controller once; later sheet edits do not reassign tokens.</p>${linked.map(a=>`<div class="vtt-list-row"><span class="body-6">${e(a.name)}<small>${a.hostile?'NPC':a.controller_name||'GM controlled'} · ${a.hp}/${a.max_hp} HP</small></span>${button('Select token',`type="button" data-vtt-action="sheet-select-token" data-id="${e(a.id)}"`)}${gm?button('Unlink',`type="button" data-vtt-action="sheet-unlink" data-id="${e(a.id)}" data-sheet="${e(sheet.id)}"`):''}</div>`).join('')||'<p class="caption-4 muted">No visible linked tokens in this scene. The GM can link or place one below.</p>'}</section>${gm?form('sheet-link','Link an existing token',`<input type="hidden" name="sheet_id" value="${e(sheet.id)}">`+select('Token to link','token_id',actorChoices(),draft('sheet-link','token_id',state.selectedActor))+'<p class="caption-4 muted">Replaces this token’s sheet reference. Its HP and controller will stay unchanged.</p>','Link token')+form('sheet-place','Place a token from this sheet',`<input type="hidden" name="sheet_id" value="${e(sheet.id)}">`+field('Token name','name',f('name',sheet.name.slice(0,60)),'text','required maxlength="60"')+field('Starting hit points','hp',f('hp',20),'number','min="1" max="999" required')+field('Map column (x, starts at 0)','x',f('x',placement.x),'number',`min="0" max="${world().width-1}" required`)+field('Map row (y, starts at 0)','y',f('y',placement.y),'number',`min="0" max="${world().height-1}" required`)+check('Hostile NPC — GM controlled','hostile',f('hostile',false))+select('Placement layer','layer',[['tokens','Tokens — visible subject to sight'],['gm','GM private']],f('layer','tokens'))+'<p class="caption-4 muted">A new token uses basic defaults: movement 6, attack +3, damage 4. Sheet notes are not parsed into game rules. Choose an unoccupied, traversable cell.</p>','Place linked token'):''}`;
  }
  function sheetEntries(sheet,editable){
    const f=(key,fallback)=>draft('sheet-entry',key,fallback);
    return `<div class="tool-card stack-12">${h('Tracked inventory, spells and resources')}<p class="caption-4 muted">Use spends one quantity on the server. Spells must be prepared. Edit an entry to replenish it; effects and equipment bonuses remain manual.</p>${(sheet.entries||[]).map(x=>`<article class="stack-12"><h4 class="title-4">${e(x.name)}</h4><p class="caption-4 muted">${e(x.kind)} · ${x.quantity}/${x.capacity}${x.kind==='spell'?x.prepared?' · Prepared':' · Not prepared':''}</p>${editable?button('Use one',`type="button" data-vtt-action="entry-use" data-sheet="${e(sheet.id)}" data-id="${e(x.id)}" ${x.quantity<=0||x.kind==='spell'&&!x.prepared?'disabled':''}`)+button('Edit entry',`type="button" data-vtt-action="entry-edit" data-id="${e(x.id)}"`)+button('Remove entry',`type="button" data-vtt-action="entry-delete" data-sheet="${e(sheet.id)}" data-id="${e(x.id)}"`):''}</article>`).join('')||'<p class="body-6 muted">No tracked entries.</p>'}</div>${editable?form('sheet-entry','Add or edit a tracked entry',`<input type="hidden" name="sheet_id" value="${e(sheet.id)}"><input type="hidden" name="entry_id" value="${e(f('entry_id',''))}">`+select('Entry type','kind',[['inventory','Inventory'],['spell','Spell / ability'],['resource','Resource']],f('kind','inventory'))+field('Entry name','name',f('name',''),'text','required maxlength="100"')+field('Quantity remaining','quantity',f('quantity',1),'number','min="0" max="9999" required')+field('Capacity','capacity',f('capacity',1),'number','min="1" max="9999" required')+check('Spell prepared / item equipped','prepared',f('prepared',false)),'Save tracked entry'):''}`;
  }
  function sectionBody(section,gm){
    const w=world(),f=(id,key,value)=>draft(id,key,value);
    if(section==='environment')return environmentPanel(gm);
    if(section==='sheets'){
      const selected=(w.sheets||[]).find(x=>x.id===state.sheetEdit),canEdit=gm||selected?.controller_id===state.user?.id;
      const value=(key,fallback='')=>f('sheet',key,selected?.[key]??fallback);
      const members=state.campaignMembers?.members||[];
      return `<div class="tool-card stack-12">${h('Character sheets')}<p class="caption-4 muted">Flexible notes for any ruleset. Record stats, quantities, spell uses, and resources. Sheet values do not automatically change map combat stats.</p>${gm?button('New character sheet','type="button" data-vtt-action="sheet-new"'):''}${(w.sheets||[]).map(x=>`<article class="stack-12"><h4 class="title-4">${e(x.name)}</h4><span class="caption-4 muted">${x.shared?'Shared':'Private'}${x.controller_id===state.user?.id?' · Yours':''}</span>${button('Open sheet',`type="button" data-vtt-action="sheet-edit" data-id="${e(x.id)}"`)}${gm?button('Delete sheet',`type="button" data-vtt-action="sheet-delete" data-id="${e(x.id)}"`):''}</article>`).join('')||'<p class="body-6 muted">No character sheets available yet.</p>'}</div>${(selected||gm)&&canEdit?form('sheet',selected?'Edit character sheet':'New character sheet',`<input type="hidden" name="sheet_id" value="${e(selected?.id||'')}">`+field('Character name','name',value('name'),'text','required maxlength="100"')+(gm?select('Sheet controller','controller_id',[['','Game master only'],...members.map(m=>[m.id,m.display_name])],value('controller_id'))+button('Refresh players','type="button" data-refresh-players')+check('Share sheet with players','shared',value('shared',false)):`<input type="hidden" name="controller_id" value="${e(selected.controller_id)}">`)+textArea('Background and description','details',value('details'),12000)+textArea('Attributes and skills','stats',value('stats'),12000)+textArea('Inventory — items, quantities, equipment','inventory',value('inventory'),12000)+textArea('Spells and abilities — effects, uses, preparation','spells',value('spells'),12000)+textArea('Resources — HP notes, currency, slots, charges','resources',value('resources'),12000),'Save character sheet'):selected?`<article class="tool-card stack-12">${['details','stats','inventory','spells','resources'].map(key=>`<h4 class="title-4">${key[0].toUpperCase()+key.slice(1)}</h4><p class="body-6 vtt-handout">${e(selected[key]||'—')}</p>`).join('')}</article>`:''}${selected&&canEdit?form('sheet-roll','Roll for this character',`<input type="hidden" name="sheet_id" value="${e(selected.id)}">`+field('Dice formula','formula','1d20+0','text','required maxlength="30"')+'<p class="caption-4 muted">Roll results are shared publicly with the table.</p>','Roll dice'):''}`;
    }
    if(section==='quests')return `${gm?form('quest',f('quest','quest_id','')?'Edit quest':'New quest',`<input type="hidden" name="quest_id" value="${e(f('quest','quest_id',''))}">`+field('Quest title','title',f('quest','title',''),'text','required maxlength="100"')+textArea('Quest description','description',f('quest','description',''),12000)+textArea('Objectives — use [x] for completed tasks','objectives',f('quest','objectives',''),12000)+select('Quest status','status',[['planned','Planned'],['active','Active'],['completed','Completed'],['failed','Failed']],f('quest','status','planned'))+check('Share quest with players','shared',f('quest','shared',false)),'Save quest'):''}${(w.quests||[]).map(x=>`<article class="tool-card stack-12"><h3 class="title-4">${e(x.title)}</h3><span class="chip caption-4">${e(x.status)} · ${x.shared?'Shared':'GM private'}</span><p class="body-6 vtt-handout">${e(x.description)}</p><p class="body-6 vtt-handout">${e(x.objectives)}</p>${gm?button('Edit quest',`type="button" data-vtt-action="quest-edit" data-id="${e(x.id)}"`)+button('Delete quest',`type="button" data-vtt-action="quest-delete" data-id="${e(x.id)}"`):''}</article>`).join('')||'<p class="body-6 muted">No quests available.</p>'}`;
    if(section==='tables')return `${gm?form('rolltable','Random outcome table',`<input type="hidden" name="table_id" value="${e(f('rolltable','table_id',''))}">`+field('Table name','name',f('rolltable','name',''),'text','required maxlength="100"')+textArea('Weighted entries — one weight | result per line','entries',f('rolltable','entries','1 | A quiet road\n2 | A travelling merchant'),20000)+check('Share table and draws with players','shared',f('rolltable','shared',false))+check('Draw with replacement','replacement',f('rolltable','replacement',true)),'Save random table'):''}${(w.roll_tables||[]).map(x=>`<article class="tool-card stack-12"><h3 class="title-4">${e(x.name)}</h3><span class="caption-4 muted">${x.shared?'Shared':'GM private'} · ${x.replacement?'With replacement':'Without replacement'}</span><ul class="body-6">${x.entries.map(row=>`<li>${row.drawn?'✓ ':''}${e(row.text)} (weight ${row.weight})</li>`).join('')}</ul>${gm?['draw','reset','edit','delete'].map(action=>button(action[0].toUpperCase()+action.slice(1),`type="button" data-vtt-action="rolltable-${action}" data-id="${e(x.id)}"`)).join(''):''}</article>`).join('')||'<p class="body-6 muted">No random tables available.</p>'}<div class="tool-card stack-12">${h('Recent outcomes')}${(state.snapshot.events||[]).filter(ev=>ev.event_type==='rolltable.draw').slice(-10).map(ev=>`<p class="body-6">${e(ev.payload.message)}</p>`).join('')||'<p class="body-6 muted">No draws yet.</p>'}</div>`;
    if(section==='lighting')return form('sight','Token line of sight',check('Enable token line of sight','enabled',f('sight','enabled',w.sight_enabled))+field('Sight radius (grid cells)','radius',f('sight','radius',w.sight_radius||8),'number','min="1" max="30" required')+'<p class="caption-4 muted">Players see through their assigned living characters. Blocked terrain and closed doors act as opaque walls. Assign a character before enabling sight; a player without one sees a dark map. The GM keeps a complete view.</p><p class="caption-4 muted">Configure darkness, light sources, doors, windows and darkvision in Environment. Custom map images are masked before delivery. The included Riverside artwork is also a public sample on the landing page.</p>','Apply sight settings');
    if(section==='art')return `${form('asset','Import artwork',field('Asset name','name',f('asset','name',''),'text','required maxlength="80"')+'<label class="field"><span class="caption-4">PNG or JPEG, up to 2 MB</span><input class="field-input body-6" name="image" type="file" accept="image/png,image/jpeg" required></label>','Save artwork')}<div class="tool-card stack-12">${h('Apply to a token')}${select('Artwork target token','token_id',actorChoices(),state.artTarget||state.selectedTarget||state.selectedActor)}</div>${(w.art_assets||[]).map(asset=>`<article class="tool-card stack-12"><img class="vtt-art-preview" src="${e(asset.image_data)}" alt="${e(asset.name)}"><h3 class="title-4">${e(asset.name)}</h3>${button('Use as map',`type="button" data-vtt-action="asset-map" data-id="${e(asset.id)}"`)}${button('Use on token',`type="button" data-vtt-action="asset-token" data-id="${e(asset.id)}"`)}${button('Remove from library',`type="button" data-vtt-action="asset-delete" data-id="${e(asset.id)}"`)}</article>`).join('')||'<p class="caption-4 muted">Import artwork you have permission to use. Library originals are visible only to the GM; placed artwork is shared on its layer.</p>'}`;
    if(section==='media')return `<div class="tool-card stack-12">${h('Local voice & video')}<p class="body-6 muted">Join a direct call with other members at this table. Your browser asks before using your microphone or camera. Use localhost or HTTPS; devices must be able to connect directly.</p>${!localStream?check('Include camera video','camera',state.callCamera):''}${button(localStream?'Leave call':mediaBusy?'Waiting for device permission…':'Join voice & video',`type="button" data-vtt-action="${localStream?'media-leave':'media-join'}" ${mediaBusy?'disabled':''}`)}${localStream?button(localStream.getAudioTracks().some(t=>t.enabled)?'Mute microphone':'Unmute microphone','type="button" data-vtt-action="media-mute"'):''}<p class="caption-4 form-error" role="status">${e(callError)}</p><div class="vtt-call-grid">${localStream?'<figure><video data-local-video autoplay muted playsinline></video><figcaption class="caption-4">You</figcaption></figure>':''}${[...calls].map(([id,entry])=>`<figure><video data-call-peer="${e(id)}" autoplay playsinline></video><figcaption class="caption-4">${e(callClients[id]?.name||'Member')} · ${e(entry.pc.connectionState)}</figcaption></figure>`).join('')}</div><p class="caption-4 muted">This direct call has no relay service configured. Networks that prevent peer connections need a relay before internet-wide calling can be guaranteed.</p></div>`;
    if(section==='scenes')return `<div class="tool-card stack-12">${h('Scenes')}<p class="body-6">Active: ${e(w.scene_name||'Riverside village')}</p><p class="caption-4 muted">Switching scenes moves everyone together. Each scene saves its map, tokens, terrain, fog marks, drawings and turn order.</p>${(w.pages||[]).map(p=>`<div class="vtt-list-row"><span class="body-6">${e(p.name)}</span>${button('Open',`type="button" data-vtt-action="scene-switch" data-id="${e(p.id)}"`)}${button('Delete',`type="button" data-vtt-action="scene-delete" data-id="${e(p.id)}"`)}</div>`).join('')||'<p class="caption-4 muted">No other scenes yet.</p>'}</div>${form('scene-create','Create a scene',field('Scene name','name',f('scene-create','name',''),'text','required maxlength="80"')+check('Duplicate the current map and tokens','duplicate',f('scene-create','duplicate',false)),'Create scene')}${form('scene-rename','Rename active scene',field('Scene name','name',f('scene-rename','name',w.scene_name||'Riverside village'),'text','required maxlength="80"'),'Rename scene')}`;
    if(section==='drawings')return `${form('brush','Drawing style',select('Drawing layer','layer',[['tokens','Tokens'],['map','Map'],['gm','GM private'],['foreground','Foreground']],f('brush','layer','tokens'))+field('Stroke color','color',f('brush','color','#e7c98c'),'color')+field('Stroke width','stroke',f('brush','stroke',3),'number','min="1" max="12" required')+textArea('Annotation text','text',f('brush','text',''),500),'Use drawing style')}<div class="tool-card stack-12">${h('Draw on the map')}<div class="vtt-shapes">${[['line','Line'],['rectangle','Rectangle'],['ellipse','Circle / ellipse'],['cone','Cone'],['freehand','Freehand'],['text','Text'],['pin','Map pin']].map(([id,label])=>button(label,`type="button" data-vtt-shape="${id}"`)).join('')}</div><p class="caption-4 muted">Choose a shape, then click two cells. Text and pins use one click. Freehand uses a drag. Escape cancels.</p>${button('Undo this layer','type="button" data-vtt-action="draw-undo"')}<div class="vtt-drawing-list">${(w.drawings||[]).map(d=>`<div class="vtt-list-row"><span class="caption-4">${e(d.shape)} · ${e(d.layer||'tokens')} ${e(d.text||'')}</span>${button('Remove',`type="button" data-vtt-action="draw-delete" data-id="${e(d.id)}"`)}</div>`).join('')}</div></div>`;
    if(section==='tokens'){
      const id=f('token-config','token_id',state.selectedTarget||state.selectedActor),a=(w.actors||[]).find(a=>a.id===id)||(w.actors||[])[0];if(!a)return '<p class="body-6 muted">Add a token in Tools first.</p>';
      return form('token-config','Token appearance and control',select('Token to configure','token_id',actorChoices(),a.id)+select('Token layer','layer',[['tokens','Tokens'],['gm','GM private'],['map','Map'],['foreground','Foreground']],f('token-config','layer',a.layer||'tokens'))+`<div class="tool-fields">${field('Rotation (degrees)','rotation',f('token-config','rotation',a.rotation||0),'number','min="0" max="359" required')}${field('Size (grid cells)','size',f('token-config','size',a.size||1),'number','min="1" max="4" required')}</div>`+field('Initiative modifier','initiative_bonus',f('token-config','initiative_bonus',a.initiative_bonus||0),'number','min="-20" max="20" required')+check('Lock player movement','locked',f('token-config','locked',a.locked))+`<fieldset class="vtt-marker-options"><legend class="caption-4">Status markers</legend>${['poisoned','prone','stunned','blessed','concentrating','invisible'].map(m=>check(m,m,f('token-config',m,(a.markers||[]).includes(m)))).join('')}</fieldset>`,'Save token settings')+form('token-copy','Duplicate token',select('Token to duplicate','token_id',actorChoices(),f('token-copy','token_id',a.id))+`<div class="tool-fields">${field('Column','x',f('token-copy','x',Math.min(w.width-1,a.x+1)),'number',`min="0" max="${w.width-1}" required`)}${field('Row','y',f('token-copy','y',a.y),'number',`min="0" max="${w.height-1}" required`)}</div>`,'Duplicate token')+`<div class="tool-card stack-12">${h('Remove selected token')}<p class="caption-4 muted">${e(a.name)}. End an active token's turn before deleting it.</p>${button('Delete token',`type="button" data-vtt-action="token-delete" data-id="${e(a.id)}"`)}</div>`;
    }
    if(section==='turns')return `<div class="tool-card stack-12">${h('Party initiative')}<p class="caption-4 muted">Server rolls 1d20 plus each party character's initiative modifier. Ties keep party order. Hostile NPCs remain GM-controlled.</p>${button('Roll party initiative','type="button" data-vtt-action="initiative-roll"')}${button('Start initiative order','type="button" data-vtt-action="initiative-start"')}<ol class="vtt-initiative">${(w.initiative||[]).map(entry=>`<li class="body-6">${e((w.actors||[]).find(a=>a.id===entry.token_id)?.name||'Removed token')} <b>${entry.score}</b></li>`).join('')}</ol>${button(w.movement_paused?'Resume player movement':'Pause player movement',`type="button" data-vtt-action="pause"`)}</div>`;
    if(section==='chat')return form('chat','Table chat',`<ol class="table-chat vtt-chat">${(state.snapshot.events||[]).filter(ev=>ev.event_type==='chat.send'||ev.event_type==='dice.roll').slice(-40).map(ev=>`<li class="${ev.payload.private?'vtt-whisper':''}"><span class="caption-4 gold">${e(ev.payload.by||'Table')}${ev.payload.private?' · PRIVATE':''}</span><p class="body-6 ${ev.payload.emote?'vtt-emote':''}">${ev.event_type==='dice.roll'?e(`${ev.payload.formula}: ${(ev.payload.rolls||[]).join(' + ')} = ${ev.payload.total}`):e(ev.payload.message)}</p></li>`).join('')||'<li class="body-6 muted">No chat or dice results yet.</li>'}</ol>`+select('Speak as','as_character',[['','Your account'],...(w.actors||[]).filter(a=>(gm||!a.hostile)&&controlsActor(a)).map(a=>[a.id,a.name])],f('chat','as_character',''))+textArea('Chat message','message',f('chat','message',''),1000)+`<p class="caption-4 muted">Enter sends; Shift+Enter adds a line. /roll 2d6+3 · /gmroll d20 · /w gm message · /w "Player name" message · /em waves. Simple NdS±bonus dice formulas are supported.</p>`,'Send chat');
    if(section==='journal'){
      const list=(w.handouts||[]).map(item=>`<article class="tool-card stack-12"><h3 class="title-4">${e(item.title)}</h3><span class="caption-4 ${item.shared?'gold':'muted'}">${item.shared?'Shared with players':'GM private'}</span><p class="body-6 vtt-handout">${e(item.text)}</p>${gm?`<div class="vtt-list-row">${button('Edit',`type="button" data-vtt-action="handout-edit" data-id="${e(item.id)}"`)}${button('Delete',`type="button" data-vtt-action="handout-delete" data-id="${e(item.id)}"`)}</div>`:''}</article>`).join('');
      return `${gm?form('handout',f('handout','handout_id','')?'Edit handout':'New handout',`<input type="hidden" name="handout_id" value="${e(f('handout','handout_id',''))}">`+field('Handout title','title',f('handout','title',''),'text','required maxlength="100"')+textArea('Handout text','text',f('handout','text',''))+check('Share with players','shared',f('handout','shared',false)),'Save handout'):''}${list||'<p class="body-6 muted">No shared handouts yet.</p>'}`;
    }
    if(section==='music')return `${gm?form('audio','Shared soundtrack',field('Track title','title',f('audio','title',w.audio?.title||''),'text','maxlength="100"')+field('Audio URL','url',f('audio','url',w.audio?.url||''),'url','placeholder="https://…/track.mp3"')+check('Play for the table','playing',f('audio','playing',w.audio?.playing)),'Update soundtrack'):''}<div class="tool-card stack-12">${h('Your audio')}<p class="body-6">${e(w.audio?.title||'No soundtrack selected')}${w.audio?.playing?' · Playing':' · Stopped'}</p>${button(audioEnabled?'Mute table audio':'Enable table audio','type="button" data-vtt-action="audio-enable"')}<label class="field"><span class="caption-4">Volume</span><input type="range" min="0" max="100" value="${state.audioVolume??50}" data-vtt-volume aria-label="Table audio volume"></label><p class="caption-4 muted">Enable audio once per browser. The source must allow browser playback. Start positions sync when listeners join; each listener controls volume.</p><p class="caption-4 muted" data-audio-status>${e(state.audioError||'')}</p></div>`;
    if(section==='macros')return `${form('macro','Save a dice macro',field('Macro name','name',f('macro','name',''),'text','required maxlength="60"')+field('Dice formula','formula',f('macro','formula','1d20+0'),'text','required maxlength="30"'),'Save macro')}<div class="tool-card stack-12">${h('Your dice macros')}<p class="caption-4 muted">Definitions are private to your account. Running a macro shares a server-resolved roll with the table.</p>${(w.macros||[]).map(m=>`<div class="vtt-list-row"><span class="body-6">${e(m.name)}<small>${e(m.formula)}</small></span>${button('Roll',`type="button" data-vtt-action="macro-run" data-id="${e(m.id)}"`)}${button('Delete',`type="button" data-vtt-action="macro-delete" data-id="${e(m.id)}"`)}</div>`).join('')||'<p class="caption-4 muted">No saved macros yet.</p>'}</div>`;
    return `${gm?form('grid','Scene grid and ruler',`<div class="tool-fields">${field('Grid columns','width',f('grid','width',w.width),'number','min="2" max="100" required')}${field('Grid rows','height',f('grid','height',w.height),'number','min="2" max="100" required')}</div>`+field('Distance per cell','scale',f('grid','scale',w.scale||1),'number','min="0.01" max="1000" step="0.01" required')+field('Distance unit','unit',f('grid','unit',w.unit||'spaces'),'text','maxlength="16" required')+select('Ruler distance','metric',[['manhattan','Orthogonal'],['euclidean','Straight-line'],['chebyshev','One unit per diagonal']],f('grid','metric',w.metric||'manhattan'))+'<p class="caption-4 muted">Movement still follows paths along the square grid. Shrinking the map requires moving tokens and removing outlying drawings/terrain first.</p>','Save scene grid')+`<div class="tool-card stack-12">${h('Player preview')}<p class="caption-4 muted">Inspect a read-only, unassigned player view. GM-layer objects, private handouts and other accounts’ private messages are omitted by the server.</p>${button('Preview as player','type="button" data-vtt-action="preview"')}</div>`:''}<div class="tool-card stack-12">${h('Your view')}<label class="field"><span class="caption-4">Map zoom</span><input type="range" min="25" max="250" step="5" value="${Math.round((state.mapZoom||1)*100)}" data-vtt-zoom aria-label="Map zoom percentage"></label>${button('Fit map','type="button" data-vtt-action="fit"')}${button('Share last ruler','type="button" data-vtt-action="measure-share"')}${button('Go to game lobby',`type="button" data-vtt-action="lobby"`)}<p class="caption-4 muted">Keyboard: 1 select · 2 pan · G grid · +/- zoom · Escape cancel. Drag a token you control to submit movement.</p></div>`;
  }
  function open(section){state.vttSection=section;selectInspectorTab('table');renderTable(state.selectedCampaign);document.querySelector('.table-sidebar')?.classList.add('is-open');}
  function environmentPanel(gm){
    const w=world(),f=(id,key,value)=>draft(id,key,value),position=id=>`<div class="tool-fields">${field('Column','x',f(id,'x',5),'number',`min="0" max="${w.width-1}" required`)}${field('Row','y',f(id,'y',5),'number',`min="0" max="${w.height-1}" required`)}</div>`;
    return `<div class="tool-card stack-12">${h('Doors and windows')}<p class="caption-4 muted">Closed doors block movement and sight. Closed windows block movement but allow sight. Players can toggle visible unlocked doors from an adjacent assigned character.</p>${(w.doors||[]).map(d=>`<article class="stack-12"><h4 class="title-4">${e(d.name)} · ${d.window?'Window':'Door'}</h4><p class="caption-4 muted">${d.x}, ${d.y} · ${d.open?'Open':'Closed'}${d.locked?' · Locked':''}${d.secret?' · Secret':''}</p>${button(d.open?'Close':'Open',`type="button" data-vtt-action="door-toggle" data-id="${e(d.id)}" ${d.locked?'disabled':''}`)}${gm?button('Edit',`type="button" data-vtt-action="door-edit" data-id="${e(d.id)}"`)+button('Remove',`type="button" data-vtt-action="door-delete" data-id="${e(d.id)}"`):''}</article>`).join('')||'<p class="body-6 muted">No visible doors.</p>'}</div>${gm?form('door','Add or edit a door',`<input type="hidden" name="door_id" value="${e(f('door','door_id',''))}">`+field('Door name','name',f('door','name',''),'text','required maxlength="80"')+position('door')+check('Open','open',f('door','open',false))+check('Locked','locked',f('door','locked',false))+check('Secret — hide from players','secret',f('door','secret',false))+check('Window — transparent to sight','window',f('door','window',false)),'Save doorway')+form('illumination','Scene darkness',check('Require light to see','require_light',f('illumination','require_light',w.require_light))+'<p class="caption-4 muted">Enable token sight in Lighting first. Light illuminates cells within token sight range; darkvision sees through darkness. Opaque walls and closed doors stop both.</p>','Apply darkness')+form('vision','Token darkvision',select('Vision token','token_id',actorChoices(),f('vision','token_id',state.selectedActor))+field('Darkvision radius (0 disables)','darkvision',f('vision','darkvision',0),'number','min="0" max="30" required'),'Save darkvision')+form('light','Add or edit a light',`<input type="hidden" name="light_id" value="${e(f('light','light_id',''))}">`+field('Light name','name',f('light','name',''),'text','required maxlength="80"')+position('light')+field('Light radius','radius',f('light','radius',6),'number','min="1" max="30" required')+field('Light color','color',f('light','color','#e7c98c'),'color')+check('Light enabled','enabled',f('light','enabled',true)),'Save light')+`<div class="tool-card stack-12">${h('Light sources')}${(w.lights||[]).map(l=>`<article><p class="body-6">${e(l.name)} · ${l.x}, ${l.y} · radius ${l.radius} · ${l.enabled?'On':'Off'}</p>${button('Edit light',`type="button" data-vtt-action="light-edit" data-id="${e(l.id)}"`)}${button('Remove light',`type="button" data-vtt-action="light-delete" data-id="${e(l.id)}"`)}</article>`).join('')}</div>`+form('crop','Crop and align custom map',`<p class="caption-4 muted">Crop percentage bounds of the current image, then rotate. The result fits the existing scene grid. This replaces the current image; retain the original file to undo. Tokens and terrain keep their grid coordinates.</p><div class="tool-fields">${field('Left percent','left',f('crop','left',0),'number','min="0" max="99" required')}${field('Top percent','top',f('crop','top',0),'number','min="0" max="99" required')}${field('Right percent','right',f('crop','right',100),'number','min="1" max="100" required')}${field('Bottom percent','bottom',f('crop','bottom',100),'number','min="1" max="100" required')}</div>`+select('Image rotation','rotation',[[0,'0°'],[90,'90°'],[180,'180°'],[270,'270°']],f('crop','rotation',0)),'Apply map crop'):''}`;
  }
  function tools(){return [['vtt-text','T','Text'],['vtt-freehand','✎','Draw'],['vtt-pin','⌖','Pin'],['vtt-fx','✧','FX']].filter(([id])=>state.isGM).map(([id,icon,label])=>`<button class="map-tool ${state.mapMode===id?'is-active':''}" data-map-tool="${id}" aria-pressed="${state.mapMode===id}" aria-label="${label} tool"><span aria-hidden="true">${icon}</span><span class="caption-4">${label}</span></button>`).join('')+`<button class="map-tool" data-vtt-open="chat" aria-label="Open table chat"><span aria-hidden="true">☏</span><span class="caption-4">Chat</span></button><button class="map-tool" data-vtt-open="settings" aria-label="Table settings"><span aria-hidden="true">⚙</span><span class="caption-4">Table</span></button>`;}
  function cell(event){const board=document.querySelector('.map-world');if(!board)return null;const r=board.getBoundingClientRect(),w=world();return{x:Math.min(w.width-1,Math.max(0,Math.floor((event.clientX-r.left)/r.width*w.width))),y:Math.min(w.height-1,Math.max(0,Math.floor((event.clientY-r.top)/r.height*w.height))) };}
  function brush(){const f=state.vttDrafts?.brush||{};return {layer:f.layer||'tokens',color:f.color||'#e7c98c',stroke:Number(f.stroke||3),text:f.text||''};}
  async function saveDrawing(shape,p,q,points){if(['text','pin'].includes(shape)&&!brush().text.trim()){notify('Enter annotation text in Table → Drawings first.');open('drawings');return;}await command({type:'draw.add',shape,...brush(),x:p.x,y:p.y,to_x:q.x,to_y:q.y,...(points?{points}:{})});}
  function shapeMarkup(d){const a=d.from,b=d.to,x=a.x*40+20,y=a.y*40+20,tx=b.x*40+20,ty=b.y*40+20,color=e(d.color||'#e7c98c'),stroke=Number(d.stroke||3),base=`stroke="${color}" stroke-width="${stroke}" fill="none"`;
    if(d.shape==='freehand'&&d.path?.length)return `<path d="${window.AstralisSmoothPath(d.path)}" ${base} stroke-linecap="round" stroke-linejoin="round"/>`;
    if(d.shape==='text'||d.shape==='pin')return `${d.shape==='pin'?`<circle cx="${x}" cy="${y}" r="9" fill="${color}"/>`:''}<text x="${x+12}" y="${y-10}" fill="${color}" font-size="18" stroke="#181818" stroke-width="3" paint-order="stroke">${e(d.text)}</text>`;
    if(d.shape==='freehand')return window.AstralisSmoothPath?`<path d="${window.AstralisSmoothPath((d.points||[]).map(p=>({x:p.x+.5,y:p.y+.5})))}" ${base} stroke-linecap="round" stroke-linejoin="round"/>`:`<polyline points="${(d.points||[]).map(p=>`${p.x*40+20},${p.y*40+20}`).join(' ')}" ${base}/>`;
    if(d.shape==='line')return `<line x1="${x}" y1="${y}" x2="${tx}" y2="${ty}" ${base}/>`;
    if(d.shape==='ellipse')return `<ellipse cx="${(x+tx)/2}" cy="${(y+ty)/2}" rx="${Math.max(10,Math.abs(tx-x)/2)}" ry="${Math.max(10,Math.abs(ty-y)/2)}" ${base}/>`;
    if(d.shape==='cone'){const dx=tx-x,dy=ty-y;return `<polygon points="${x},${y} ${tx-dy/2},${ty+dx/2} ${tx+dy/2},${ty-dx/2}" ${base}/>`;}
    return `<rect x="${Math.min(x,tx)-20}" y="${Math.min(y,ty)-20}" width="${Math.abs(tx-x)+40}" height="${Math.abs(ty-y)+40}" ${base}/>`;
  }
  function syncAudio(){const track=world().audio||{};if(!audioEnabled||!track.playing||!track.url){audio?.pause();return;}const key=track.url+'|'+track.started_at;if(key===audioKey)return;audioKey=key;audio?.pause();audio=new Audio(track.url);audio.volume=(state.audioVolume??50)/100;audio.loop=true;audio.onloadedmetadata=()=>{if(Number.isFinite(audio.duration)&&audio.duration>0){audio.currentTime=Math.max(0,(Date.now()-Date.parse(track.started_at))/1000)%audio.duration;}};audio.onerror=()=>{state.audioError='This audio source could not be played. Check the URL and source permissions.';const label=document.querySelector('[data-audio-status]');if(label)label.textContent=state.audioError;};audio.play().catch(()=>{state.audioError='Your browser blocked playback. Enable audio again to retry.';audioKey='';});}
  function mediaRender(){if(currentRoute().startsWith('/table/')&&state.vttSection==='media'&&state.inspectorTab==='table')renderTable(state.selectedCampaign);}
  function leaveCall(send=true){if(send)ctx.sendLive({type:'rtc.leave'});localStream?.getTracks().forEach(t=>t.stop());localStream=null;for(const entry of calls.values())entry.pc.close();calls.clear();mediaBusy=false;}
  function attachMedia(){const self=document.querySelector('[data-local-video]');if(self&&self.srcObject!==localStream)self.srcObject=localStream;for(const [id,entry] of calls){const video=document.querySelector(`[data-call-peer="${id}"]`);if(video&&entry.stream&&video.srcObject!==entry.stream){video.srcObject=entry.stream;video.play().catch(()=>{});}}}
  function peer(id){if(calls.has(id))return calls.get(id);const pc=new RTCPeerConnection({iceServers:[]}),entry={pc,candidates:[],stream:null};calls.set(id,entry);localStream?.getTracks().forEach(t=>pc.addTrack(t,localStream));pc.onicecandidate=event=>{if(event.candidate)ctx.sendLive({type:'rtc.signal',to:id,payload:{kind:'candidate',candidate:event.candidate.toJSON()}});};pc.ontrack=event=>{entry.stream=event.streams[0];mediaRender();attachMedia();};pc.onconnectionstatechange=()=>{if(pc.connectionState==='failed')callError='A peer connection failed. Rejoin the call, or use a network that allows direct connections.';mediaRender();};return entry;}
  async function reconcileCall(){if(!localStream)return;for(const [id,entry] of calls){if(!callClients[id]?.media){entry.pc.close();calls.delete(id);}}for(const [id,client]of Object.entries(callClients)){if(id===connectionID||!client.media||calls.has(id))continue;const entry=peer(id);if(connectionID<id){try{await entry.pc.setLocalDescription(await entry.pc.createOffer());ctx.sendLive({type:'rtc.signal',to:id,payload:{kind:'offer',description:entry.pc.localDescription.toJSON()}});}catch{callError='Could not start a peer connection.';}}}mediaRender();}
  async function onLive(message){try{if(message.type==='session.sync')connectionID=message.connection_id||'';if(message.type==='presence'){callClients=message.clients||{};await reconcileCall();}if(message.type==='rtc.signal'&&localStream&&callClients[message.from]?.media){const entry=peer(message.from),p=message.payload;if(p.kind==='candidate'){if(entry.pc.remoteDescription)await entry.pc.addIceCandidate(p.candidate);else entry.candidates.push(p.candidate);}else if(p.kind==='offer'||p.kind==='answer'){await entry.pc.setRemoteDescription(p.description);for(const candidate of entry.candidates)await entry.pc.addIceCandidate(candidate);entry.candidates=[];if(p.kind==='offer'){await entry.pc.setLocalDescription(await entry.pc.createAnswer());ctx.sendLive({type:'rtc.signal',to:message.from,payload:{kind:'answer',description:entry.pc.localDescription.toJSON()}});}}}if(message.type==='closed'){if(localStream)callError='Connection closed. Join again when the table reconnects.';leaveCall(false);connectionID='';}}catch{callError='A call negotiation failed. Leave and join again to retry.';mediaRender();}}
  function afterRender(){const w=world(),board=document.querySelector('.map-world');if(!board)return;
    canvas?.prepare();
    document.querySelectorAll('.vtt-layer-overlay').forEach(el=>el.remove());
    board.insertAdjacentHTML('beforeend',`<svg class="vtt-layer-overlay vtt-layer-foreground" viewBox="0 0 ${w.width*40} ${w.height*40}" preserveAspectRatio="none" aria-hidden="true">${(w.doors||[]).map(d=>`<rect x="${d.x*40+5}" y="${d.y*40+5}" width="30" height="30" rx="3" stroke="${d.window?'#8bd0d9':'#e7c98c'}" stroke-width="3" fill="${d.open?'none':'#302b25'}" stroke-dasharray="${d.secret?'4 3':'none'}"/><text x="${d.x*40+20}" y="${d.y*40+25}" text-anchor="middle" fill="#fff" font-size="13">${d.locked?'L':d.window?'W':'D'}</text>`).join('')}${(w.lights||[]).filter(l=>l.enabled).map(l=>`<circle cx="${l.x*40+20}" cy="${l.y*40+20}" r="7" fill="${e(l.color)}" stroke="#fff" stroke-width="2"/>`).join('')}</svg>`);
    if(w.sight_enabled&&!state.isGM){const cells=new Set((w.visible_cells||[]).map(p=>p.x+','+p.y));let mask='';for(let y=0;y<w.height;y++)for(let x=0;x<w.width;x++)if(!cells.has(x+','+y))mask+=`<rect x="${x*40}" y="${y*40}" width="40" height="40"/>`;board.insertAdjacentHTML('beforeend',`<svg class="vtt-layer-overlay vtt-sight-mask" viewBox="0 0 ${w.width*40} ${w.height*40}" preserveAspectRatio="none" aria-hidden="true" fill="#121212">${mask}</svg>`);}
    for(const layer of ['map','tokens','gm','foreground']){const drawings=(w.drawings||[]).filter(d=>d.layer===layer);if(drawings.length)board.insertAdjacentHTML('beforeend',`<svg class="vtt-layer-overlay vtt-layer-${layer}" viewBox="0 0 ${w.width*40} ${w.height*40}" preserveAspectRatio="none" aria-hidden="true">${drawings.map(shapeMarkup).join('')}</svg>`);}
    document.querySelectorAll('.map-token').forEach(el=>{const a=(w.actors||[]).find(a=>a.id===el.dataset.actorId);if(!a)return;el.dataset.layer=a.layer||'tokens';el.style.rotate=`${a.rotation||0}deg`;if(a.size>1){el.style.width=`calc(${a.size/w.width*100}% - 6px)`;el.style.height=`calc(${a.size/w.height*100}% - 6px)`;el.style.left=`${(a.x+a.size/2)/w.width*100}%`;el.style.top=`${(a.y+a.size/2)/w.height*100}%`;}if(a.token_image){el.style.backgroundImage=`url("${a.token_image}")`;el.style.backgroundSize='cover';el.style.backgroundPosition='center';el.style.color='transparent';}if(a.layer==='gm')el.style.opacity='.5';if(a.layer==='map')el.style.zIndex='2';if(a.layer==='foreground')el.style.zIndex='6';el.setAttribute('aria-label',`${el.getAttribute('aria-label')}${a.locked?', movement locked':''}${a.markers?.length?', '+a.markers.join(', '):''}`);if(a.markers?.length)el.insertAdjacentHTML('beforeend',`<span class="vtt-token-markers">${a.markers.map(m=>`<span title="${e(m)}" aria-label="${e(m)}">${e(m.slice(0,1).toUpperCase())}</span>`).join('')}</span>`);});
    const scene=w.scene_name||'Riverside village';const label=document.querySelector('.scene-breadcrumb');if(label)label.innerHTML=`<span class="scene-live-dot"></span>${e(scene)} <span class="muted">/ Battle map</span>`;
    syncAudio();
    canvas?.afterRender();
    attachMedia();
    const latest=[...(state.snapshot.events||[])].reverse().find(ev=>ev.event_type==='fx.burst');if(!window.AstralisSystems&&latest&&Date.now()-Date.parse(latest.created_at)<4000&&latest.payload.point){const p=latest.payload.point;board.insertAdjacentHTML('beforeend',`<span class="vtt-burst" style="left:${(p.x+.5)/w.width*100}%;top:${(p.y+.5)/w.height*100}%" aria-hidden="true"></span>`);}
    const measurement=[...(state.snapshot.events||[])].reverse().find(ev=>ev.event_type==='measure.share');if(!window.AstralisSystems&&measurement&&Date.now()-Date.parse(measurement.created_at)<30000){const a=measurement.payload.point,b=measurement.payload.to;board.insertAdjacentHTML('beforeend',`<svg class="vtt-layer-overlay vtt-layer-foreground" viewBox="0 0 ${w.width*40} ${w.height*40}" preserveAspectRatio="none" aria-hidden="true"><line x1="${a.x*40+20}" y1="${a.y*40+20}" x2="${b.x*40+20}" y2="${b.y*40+20}" stroke="#8bd0d9" stroke-width="3" stroke-dasharray="6 3"/><text x="${b.x*40+20}" y="${b.y*40+10}" fill="#8bd0d9" font-size="16">${e(measurement.payload.distance)} ${e(measurement.payload.unit||'spaces')}</text></svg>`);}
  }
  function init(){
    canvas?.init();
    document.addEventListener('click',async event=>{
      const section=event.target.closest('[data-vtt-section]')?.dataset.vttSection||event.target.closest('[data-vtt-open]')?.dataset.vttOpen;if(section){open(section);return;}
      const shape=event.target.closest('[data-vtt-shape]')?.dataset.vttShape;if(shape){state.mapMode='vtt-'+shape;state.vttStart=null;state.tableMessage=shape==='freehand'?'Drag across the map to draw.':'Click the map to place '+shape+'.';renderTable(state.selectedCampaign);document.querySelector('.table-sidebar')?.classList.remove('is-open');return;}
      const action=event.target.closest('[data-vtt-action]');if(action){const name=action.dataset.vttAction,id=action.dataset.id;const actions={'scene-switch':{type:'scene.switch',scene_id:id},'scene-delete':{type:'scene.delete',scene_id:id},'draw-delete':{type:'draw.delete',drawing_id:id},'draw-undo':{type:'draw.undo',layer:brush().layer},'token-delete':{type:'token.delete',token_id:id},'initiative-roll':{type:'initiative.roll'},'initiative-start':{type:'initiative.start'},'pause':{type:'table.pause',paused:!world().movement_paused},'handout-delete':{type:'handout.delete',handout_id:id},'macro-delete':{type:'macro.delete',macro_id:id},'macro-run':{type:'macro.run',macro_id:id}};
        if(name==='token-sheet'){state.sheetEdit=id;state.editorToken='';state.vttDrafts??={};delete state.vttDrafts.sheet;delete state.vttDrafts['sheet-entry'];delete state.vttDrafts['sheet-place'];delete state.vttDrafts['sheet-link'];state.sidebarCollapsed=false;open('sheets');return;}
        if(name==='sheet-select-token'){const a=(world().actors||[]).find(x=>x.id===id);if(a?.hostile)state.selectedTarget=id;else state.selectedActor=id;renderTable(state.selectedCampaign);return;}
        if(name==='sheet-unlink'){await command({type:'sheet.link',sheet_id:action.dataset.sheet,token_id:id,unlink:true});return;}
        if(name==='sheet-new'||name==='sheet-edit'){state.sheetEdit=id||'';state.vttDrafts??={};delete state.vttDrafts.sheet;delete state.vttDrafts['sheet-entry'];delete state.vttDrafts['sheet-place'];delete state.vttDrafts['sheet-link'];renderTable(state.selectedCampaign);return;}
        if(name==='entry-edit'){const sheet=(world().sheets||[]).find(x=>x.id===state.sheetEdit);state.vttDrafts??={};state.vttDrafts['sheet-entry']={...sheet.entries.find(x=>x.id===id),entry_id:id};renderTable(state.selectedCampaign);return;}
        if(name==='entry-use'||name==='entry-delete'){await command({type:name==='entry-use'?'sheet.entry.use':'sheet.entry.delete',sheet_id:action.dataset.sheet,entry_id:id});return;}
        if(name==='door-edit'||name==='light-edit'){const key=name.split('-')[0],list=key==='door'?world().doors:world().lights;state.vttDrafts??={};state.vttDrafts[key]={...list.find(x=>x.id===id),[key+'_id']:id};renderTable(state.selectedCampaign);return;}
        if(['door-toggle','door-delete','light-delete'].includes(name)){await command({type:name.replace('-','.'),[name.startsWith('door')?'door_id':'light_id']:id});return;}
        if(name==='sheet-delete'){await command({type:'sheet.delete',sheet_id:id});state.sheetEdit='';return;}
        if(name==='quest-edit'){state.vttDrafts??={};state.vttDrafts.quest={...(world().quests||[]).find(x=>x.id===id),quest_id:id};renderTable(state.selectedCampaign);return;}
        if(name==='quest-delete'){await command({type:'quest.delete',quest_id:id});return;}
        if(name==='rolltable-edit'){const x=(world().roll_tables||[]).find(x=>x.id===id);state.vttDrafts??={};state.vttDrafts.rolltable={...x,table_id:id,entries:x.entries.map(row=>`${row.weight} | ${row.text}`).join('\n')};renderTable(state.selectedCampaign);return;}
        if(name.startsWith('rolltable-')){await command({type:name.replace('-','.'),table_id:id});return;}
        if(name==='asset-map'||name==='asset-token'||name==='asset-delete'){const target=document.querySelector('[aria-label="Artwork target token"]')?.value||state.artTarget;state.artTarget=target;await command({type:name.replace('-','.'),asset_id:id,token_id:target});return;}
        if(name==='media-join'){if(!navigator.mediaDevices?.getUserMedia||!connectionID){callError='Use localhost or HTTPS with a live table connection to join.';mediaRender();return;}mediaBusy=true;mediaRender();try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:Boolean(state.callCamera)});if(!currentRoute().startsWith('/table/')||!connectionID){stream.getTracks().forEach(t=>t.stop());return;}localStream=stream;callError='';ctx.sendLive({type:'rtc.join'});await reconcileCall();}catch(error){callError=error.name==='NotAllowedError'?'Microphone/camera access was denied. Change browser permissions to retry.':'No available media device, or device access failed.';}finally{mediaBusy=false;mediaRender();}return;}
        if(name==='media-leave'){leaveCall();mediaRender();return;}
        if(name==='media-mute'){localStream?.getAudioTracks().forEach(t=>t.enabled=!t.enabled);mediaRender();return;}
        if(actions[name]){await command(actions[name]);return;}
        if(name==='handout-edit'){state.vttDrafts??={};state.vttDrafts.handout={...(world().handouts||[]).find(h=>h.id===id),handout_id:id};renderTable(state.selectedCampaign);return;}
        if(name==='audio-enable'){audioEnabled=!audioEnabled;audioKey='';state.audioError='';syncAudio();renderTable(state.selectedCampaign);return;}
        if(name==='measure-share'){const m=state.measureResult;if(!m){notify('Use the ruler on the map first.');return;}await command({type:'measure.share',x:m.a.x,y:m.a.y,to_x:m.b.x,to_y:m.b.y,shape:m.shape||'line'});if(!state.tableError){state.measureResult=null;renderTable(state.selectedCampaign);}return;}
        if(name==='fit'){document.querySelector('[data-map-action="fit"]')?.click();return;}
        if(name==='lobby'){location.hash='/campaign/'+state.selectedCampaign.id;return;}
        if(name==='preview'||name==='exit-preview'){await ctx.preview(name==='preview');return;}
      }
      if(event.target.closest('.map-world')&&Date.now()<ignoreClick)return;
      if(!event.target.closest('.map-world')||!state.mapMode?.startsWith('vtt-')||state.commandPending)return;
      const p=cell(event),mode=state.mapMode.slice(4);if(!p||mode==='freehand')return;
      if(mode==='fx'){await command({type:'fx.burst',...p});return;}
      if(['text','pin'].includes(mode)){await saveDrawing(mode,p,p);return;}
      if(!state.vttStart){state.vttStart=p;notify('Click the end cell. Escape cancels.');return;}
      const start=state.vttStart;state.vttStart=null;await saveDrawing(mode,start,p);
    });
    document.addEventListener('input',event=>{const form=event.target.closest('[data-vtt-form]');if(form){state.vttDrafts??={};const values=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type="checkbox"]').forEach(el=>values[el.name]=el.checked);state.vttDrafts[form.dataset.vttForm]=values;}if(event.target.matches('[data-vtt-volume]')){state.audioVolume=Number(event.target.value);if(audio)audio.volume=state.audioVolume/100;}if(event.target.matches('[data-vtt-zoom]'))ctx.zoom(Number(event.target.value)/100);if(event.target.matches('input[name="camera"]'))state.callCamera=event.target.checked;});
    document.addEventListener('change',event=>{if(event.target.matches('[data-vtt-form="token-config"] [name="token_id"]')){state.vttDrafts??={};state.vttDrafts['token-config']={token_id:event.target.value};renderTable(state.selectedCampaign);}});
    document.addEventListener('submit',async event=>{const form=event.target.closest('[data-vtt-form]');if(!form)return;event.preventDefault();if(!form.reportValidity()||state.commandPending)return;const id=form.dataset.vttForm,v=Object.fromEntries(new FormData(form)),bool=name=>Boolean(form.querySelector(`[name="${name}"]`)?.checked);let payload;
      if(id==='asset'){const image=form.querySelector('[name="image"]').files[0];if(!image||image.size>2*1024*1024){notify('Choose a PNG or JPEG up to 2 MB.');return;}try{const image_data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Image could not be read.'));reader.readAsDataURL(image);});await command({type:'asset.save',name:v.name,image_data});if(!state.tableError){if(state.vttDrafts)delete state.vttDrafts.asset;renderTable(state.selectedCampaign);}}catch(error){notify(error.message);}return;}
      if(id==='brush'){notify('Drawing style selected. Choose a shape, then use the map.');return;}
      if(id==='scene-create')payload={type:'scene.create',name:v.name,duplicate:bool('duplicate')};
      if(id==='sheet-entry')payload={type:'sheet.entry.save',...v,quantity:Number(v.quantity),capacity:Number(v.capacity),prepared:bool('prepared')};
      if(id==='door')payload={type:'door.save',...v,x:Number(v.x),y:Number(v.y),open:bool('open'),locked:bool('locked'),secret:bool('secret'),window:bool('window')};
      if(id==='light')payload={type:'light.save',...v,x:Number(v.x),y:Number(v.y),radius:Number(v.radius),enabled:bool('enabled')};
      if(id==='vision')payload={type:'token.vision',token_id:v.token_id,darkvision:Number(v.darkvision)};
      if(id==='illumination')payload={type:'lighting.settings',require_light:bool('require_light')};
      if(id==='crop')payload={type:'map.calibrate',left:Number(v.left),top:Number(v.top),right:Number(v.right),bottom:Number(v.bottom),rotation:Number(v.rotation)};
      if(id==='sheet')payload={type:'sheet.save',...v,shared:state.isGM?bool('shared'):Boolean((world().sheets||[]).find(x=>x.id===v.sheet_id)?.shared)};
      if(id==='sheet-roll')payload={type:'sheet.roll',sheet_id:v.sheet_id,formula:v.formula};
      if(id==='sheet-link')payload={type:'sheet.link',sheet_id:v.sheet_id,token_id:v.token_id,unlink:false};
      if(id==='sheet-place')payload={type:'sheet.place',sheet_id:v.sheet_id,name:v.name,x:Number(v.x),y:Number(v.y),hp:Number(v.hp),hostile:bool('hostile'),layer:v.layer};
      if(id==='quest')payload={type:'quest.save',...v,shared:bool('shared')};
      if(id==='rolltable')payload={type:'rolltable.save',...v,shared:bool('shared'),replacement:bool('replacement')};
      if(id==='scene-rename')payload={type:'scene.rename',name:v.name};
      if(id==='sight')payload={type:'sight.settings',enabled:bool('enabled'),radius:Number(v.radius)};
      if(id==='grid')payload={type:'table.settings',width:Number(v.width),height:Number(v.height),scale:Number(v.scale),unit:v.unit,metric:v.metric};
      if(id==='token-config')payload={type:'token.configure',token_id:v.token_id,layer:v.layer,rotation:Number(v.rotation),size:Number(v.size),initiative_bonus:Number(v.initiative_bonus),locked:bool('locked'),markers:['poisoned','prone','stunned','blessed','concentrating','invisible'].filter(bool)};
      if(id==='token-copy')payload={type:'token.duplicate',token_id:v.token_id,x:Number(v.x),y:Number(v.y)};
      if(id==='handout')payload={type:'handout.save',handout_id:v.handout_id,title:v.title,text:v.text,shared:bool('shared')};
      if(id==='macro')payload={type:'macro.save',name:v.name,formula:v.formula};
      if(id==='audio')payload={type:'audio.set',title:v.title,url:v.url,playing:bool('playing')};
      if(id==='chat')payload={type:'chat.post',message:v.message,as_character:v.as_character};
      if(payload){await command(payload);if(!state.tableError){if(state.vttDrafts)delete state.vttDrafts[id];renderTable(state.selectedCampaign);}}
    });
    document.addEventListener('keydown',event=>{if(event.key==='Escape'){state.vttStart=null;gesture=null;}if(event.key==='Enter'&&!event.shiftKey&&event.target.matches('[data-vtt-form="chat"] textarea')){event.preventDefault();event.target.closest('form').requestSubmit();}});
    document.addEventListener('pointerdown',event=>{if(event.button!==0||state.commandPending||state.playerPreview)return;const board=event.target.closest('.map-world');if(!board)return;const token=event.target.closest('.map-token'),w=world();if(state.mapMode==='vtt-freehand'&&state.isGM){gesture={kind:'draw',start:cell(event),points:[cell(event)],board,id:event.pointerId};board.setPointerCapture(event.pointerId);}else if(token&&(!state.mapMode||state.mapMode==='select')){const a=w.actors.find(a=>a.id===token.dataset.actorId);if(!a||!controlsActor(a)||(!state.isGM&&(a.locked||w.movement_paused||a.id!==w.active_actor_id)))return;gesture={kind:'token',token:a.id,start:cell(event),px:event.clientX,py:event.clientY,board,id:event.pointerId};board.setPointerCapture(event.pointerId);}});
    document.addEventListener('pointermove',event=>{if(!gesture||gesture.id!==event.pointerId||gesture.kind!=='draw')return;const p=cell(event),last=gesture.points.at(-1);if(p&&(p.x!==last.x||p.y!==last.y)&&gesture.points.length<250)gesture.points.push(p);});
    document.addEventListener('pointerup',async event=>{if(!gesture||gesture.id!==event.pointerId)return;const g=gesture;gesture=null;const p=cell(event);if(!p)return;if(g.kind==='draw'){ignoreClick=Date.now()+300;if(g.points.length>=2)await saveDrawing('freehand',g.start,p,g.points);}else if(Math.hypot(event.clientX-g.px,event.clientY-g.py)>5){ignoreClick=Date.now()+300;await command(state.isGM?{type:'token.place',token_id:g.token,...p}:{type:'character.move',character_id:g.token,target:p});}});
    document.addEventListener('pointercancel',()=>{gesture=null;});
    window.addEventListener('hashchange',()=>{leaveCall();if(!currentRoute().startsWith('/table/')){audio?.pause();audioKey='';}});
  }
  return {panel,tools,afterRender,init,onLive,beforeRender:()=>canvas?.beforeRender()};
};
